#
#    Reads a binary MARC file and checks each 650 subject heading (with indicator 2 of 0 or 1)
#    against the Library of Congress subject and children's terms files, which must be in the
#    same folder as this script.  Headings not found in either file are reported.
#
#    Usage:  python check-subjects.py -i <MARC input file> -o <output file>
#
#    -i, --input   Path to the binary MARC input file. Required.
#    -o, --output  Path to the output report file. Required.
#
#    Generated by Claude.
#
#    Version:  0.1.1  10/1/26
#
#    License:  CC BY-NC-SA 4.0, https://creativecommons.org/licenses/by-nc-sa/4.0/
#
#    Graeme Williams
#    carryonwilliams@gmail.com
#

import argparse
import sys
import os
import unicodedata
from pathlib import Path
from typing import List

from pymarc import MARCReader

PROGRAM = "check-subjects"
VERSION = "0.1.1"

SCRIPT_DIR = Path(__file__).resolve().parent
SUBJECT_TERMS_PATH = SCRIPT_DIR / "subject-terms.txt"
CHILDRENS_TERMS_PATH = SCRIPT_DIR / "childrens-terms.txt"


# Make sure print writes in utf-8
if sys.platform == "win32":
    os.system("chcp 65001 >nul")
sys.stdout.reconfigure(encoding="utf-8")


# Unicode string normalization
def unicode_normalize(s):
    s = unicodedata.normalize("NFD", s)
    s = s.casefold()
    return unicodedata.normalize("NFD", s)


# Make sure you normalize before calling this function
def strip_punctuation(subfield : str) -> str:
    t = subfield.strip()
    t = t.rstrip(',')
    # strip trailing . unless it's an initial, like "Smith, A."
    if len(t) > 2 and t[-3].isalnum():
        t = t.rstrip('.')
    return t


def print_terminal_header(program: str, version: str, inputfile: str, outputfile: str) -> None:
    print("=" * 45)
    print(f"  {program} {version}")
    print(f"  Input:  {inputfile}")
    print(f"  Output: {outputfile}")
    print("=" * 45)


def count_phrase(n: int, singular: str, plural: str) -> str:
    return f"{n} {singular if n == 1 else plural}"


def summary_lines(total: int, skipped: int, errors: int, error_records: int) -> List[str]:
    return [
        f"{total} records processed, {skipped} skipped",
        f"{count_phrase(errors, 'error', 'errors')} found in {count_phrase(error_records, 'record', 'records')}",
    ]


def main():
    parser = argparse.ArgumentParser(description="Check subject headings in a binary MARC file.")
    parser.add_argument(
        "-i", "--input",
        dest="input_file",
        type=Path,
        required=True,
        help="Path to binary MARC file",
    )
    parser.add_argument(
        "-o", "--output",
        dest="output_file",
        type=Path,
        required=True,
        help="Path to output report file",
    )
    args = parser.parse_args()
    marc_path = args.input_file
    out_path = args.output_file

    print_terminal_header(PROGRAM, VERSION, str(marc_path), str(out_path))

    # Load terms for LC subject headings
    subject_file_path = SUBJECT_TERMS_PATH if SUBJECT_TERMS_PATH.exists() else Path("subject-terms.txt")
    subjectTermsSet = set()
    with open(subject_file_path, encoding="utf-8-sig") as subjectFile:
        for phrase in subjectFile:
            term = strip_punctuation(unicode_normalize(phrase))
            if term:
                subjectTermsSet.add(term)

    # Load terms for LC children's headings
    childrens_file_path = CHILDRENS_TERMS_PATH if CHILDRENS_TERMS_PATH.exists() else Path("childrens-terms.txt")
    childrenstermsSet = set()
    with open(childrens_file_path, encoding="utf-8-sig") as childrensFile:
        for phrase in childrensFile:
            term = strip_punctuation(unicode_normalize(phrase))
            if term:
                childrenstermsSet.add(term)

    loaded_msg = f"Loaded {len(subjectTermsSet)} subject terms and {len(childrenstermsSet)} children's terms."
    print(loaded_msg)
    print(" ")

    if not marc_path.exists():
        print(f"Error: MARC file not found: {marc_path}")
        return

    total_records = 0
    skipped_records = 0
    errors_found = 0
    error_records = 0

    with open(out_path, "w", encoding="utf-8") as out_f:
        out_f.write(f"# {PROGRAM} {VERSION}\n")
        out_f.write(f"# Input:  {marc_path}\n")
        out_f.write(f"# Output: {out_path}\n")
        out_f.write(f"# {loaded_msg}\n")
        out_f.write("# " + "-" * 72 + "\n")

        def emit(line: str) -> None:
            # Detail goes to the output file only; the terminal shows the summary
            out_f.write(line + "\n")

        with open(marc_path, "rb") as marc_input:
            reader = MARCReader(marc_input)
            for record in reader:
                if record is None:
                    skipped_records += 1
                    continue
                total_records += 1
                fields_001 = record.get_fields('001')
                item_id = fields_001[0].value() if fields_001 else ""
                title = record.title.rstrip(" /:.=") if record.title else "No title"
                errors = []
                for field in record.get_fields("650"):
                    if field.indicator2 in {'0', '1'}:
                        for subfield in field.get_subfields("a", "b", "x"):
                            normalized = strip_punctuation(unicode_normalize(subfield))
                            if normalized not in subjectTermsSet and normalized not in childrenstermsSet:
                                if f"{field}" not in errors:
                                    errors.append(f"{field}")
                if errors:
                    error_records += 1
                    errors_found += len(errors)
                    id_prefix = f"Item {item_id} " if item_id else ""
                    emit(f"{id_prefix}{title} — subject headings not in LoC:")
                    for error in errors:
                        emit(f"  {error}")

        out_f.write("# " + "-" * 72 + "\n")
        summary = summary_lines(total_records, skipped_records, errors_found, error_records)
        for line in summary:
            out_f.write(f"# {line}\n")

    for line in summary:
        print(line)
    print("=" * 45)
    print(f"Detailed report written to: {out_path}\n")


if __name__ == "__main__":
    main()
